import{z as i,x as A,o as t,c as d,q as r,j as n,D as E,d as s,s as B,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"TEE：SGX / TrustZone","description":"","frontmatter":{"title":"TEE：SGX / TrustZone","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tee-sgx-trustzone.md","filePath":"cs/tee-sgx-trustzone.md","lastUpdated":1791413859000}'),p={name:"cs/tee-sgx-trustzone.md"};function u(T,a,S,h,m,D){const o=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="tee-sgx-trustzone" tabindex="-1">TEE：SGX / TrustZone <a class="header-anchor" href="#tee-sgx-trustzone" aria-label="Permalink to &quot;TEE：SGX / TrustZone&quot;">​</a></h1><div class="epigraph"><p>可信执行环境把敏感代码放进与操作系统隔离的飞地。SGX 在进程内划飞地，TrustZone 划安全世界。TCB 变小，但侧信道、接口与供应仍在模型里。</p><footer>—— Costan and Devadas, Intel SGX Explained；ARM TrustZone 白皮书；对照[隔离](/cs/isolation-sandbox)</footer></div><p>上一课<a href="/cs/windows-kerberos-attacks">Kerberos</a>的票据密钥仍躺在 OS 内存里，内核被攻破即全丢。缺口是<strong>对 OS 也不信任时</strong>的盒子。本课对照 SGX 与 TrustZone，不写飞地攻击步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HSM 是机箱外的盒子，边界清晰但部署重；TEE 把盒子搬进 CPU：SGX 在进程地址空间里划飞地，TrustZone 把整颗芯片分成普通/安全两个世界。飞地可密封数据（绑定芯片与代码度量的加密）、可远程证明（后课）。但「对 OS 零信任」不是零交互：OS 仍负责调度、供页与中断，页换出、TLB 操纵都是侧信道入口——威胁模型必须把侧信道明写进去，否则等于赌敌手只走功能正确的 API。</p><h3 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h3><p>飞地与不可信世界的调用约定是新攻击面：参数怎么传、指针能否指向飞地内、异常如何回卷，每一项都对应一类混淆代理或 TOCTOU 缺陷，要当协议审，不能当函数调用看。</p><p><span class="marginnote">Costan–Devadas。SGX 的公开研究含侧信道，本课不复现。机密计算下一课把 TEE 收到云产品叙事。</span></p><p><span class="marginnote">术语翻译：TCB（可信计算基）是&quot;安全承诺赖以成立的最小软硬件清单&quot;——清单上任何一环作恶或被攻破，承诺就作废；所谓缩小 TCB，就是把必须信任的东西变少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照两个粒度：TrustZone 在硬件层分世界，安全世界有自己的内核与外设，粒度粗、迁移成本高；SGX 飞地在用户态进程内，粒度细、存量代码不动，代价是系统调用要出飞地代跳。内存加密引擎的角色要指出：DRAM 上的飞地页被加密并挂完整性树，内存总线探头读到的是密文与校验失败。下一课机密计算。</p>',12)),(t(),n(l,null,{default:E(()=>[B(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OS%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%20OS%22%5D%20--%3E%20EE%5B%22%E9%A3%9E%E5%9C%B0%E6%88%96%E5%AE%89%E5%85%A8%E4%B8%96%E7%95%8C%22%5D%0A%20%20EE%20--%3E%20SEAL%5B%22%E5%AF%86%E5%B0%81%E5%AF%86%E9%92%A5%22%5D%0A%20%20OS%20-.-%3E%7C%22%E4%BE%A7%E4%BF%A1%E9%81%93%E4%B8%8E%E6%8E%A5%E5%8F%A3%22%7C%20EE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"TEE 的本质是把 TCB 从「整个 OS 加 hypervisor」缩到「CPU 微码加飞地代码」：信任面小了几个量级，但没有归零——微码缺陷、封装的加密基元、上面那道调用接口都还在盒子里。远程证明下一课让远端相信飞地的度量值；机密计算把同一思想卖给云租户：你连云厂商运维也不必信，但换成了要信芯片厂。",-1)),a[5]||(a[5]=e("p",null,"把两种信任面摆在一起，缩掉了什么、留下了什么一目了然：",-1)),(t(),n(l,null,{default:E(()=>[B(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BC%A0%E7%BB%9F%E6%A0%88%E7%9A%84%E4%BF%A1%E4%BB%BB%E5%9F%BA%22%5D%20--%3E%20O1%5B%22%E5%BA%94%E7%94%A8%E4%BB%A3%E7%A0%81%22%5D%0A%20%20O1%20--%3E%20O2%5B%22%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%86%85%E6%A0%B8%22%5D%0A%20%20O2%20--%3E%20O3%5B%22hypervisor%22%5D%0A%20%20O3%20--%3E%20BAD%5B%22%E4%BB%BB%E4%B8%80%E5%B1%82%E8%A2%AB%E6%94%BB%E7%A0%B4%E5%8D%B3%E5%A4%B1%E5%AE%88%22%5D%0A%20%20T2%5B%22TEE%20%E7%9A%84%E4%BF%A1%E4%BB%BB%E5%9F%BA%22%5D%20--%3E%20E1%5B%22%E9%A3%9E%E5%9C%B0%E5%86%85%E7%9A%84%E4%BB%A3%E7%A0%81%22%5D%0A%20%20E1%20--%3E%20E2%5B%22CPU%20%E5%BE%AE%E7%A0%81%E4%B8%8E%E7%A1%AC%E4%BB%B6%22%5D%0A%20%20E2%20--%3E%20E3%5B%22OS%20%E5%8F%AA%E8%B4%9F%E8%B4%A3%E4%BE%9B%E9%A1%B5%E4%B8%8E%E8%B0%83%E5%BA%A6%22%5D%0A%20%20E3%20--%3E%20SIDE%5B%22OS%20%E4%BD%9C%E6%81%B6%E5%8F%AA%E5%89%A9%E4%BE%A7%E4%BF%A1%E9%81%93%E4%B8%80%E6%9D%A1%E8%B7%AF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：密封像把日记锁进保险箱，钥匙由&quot;这本日记的内容&quot;和&quot;写它的那台芯片&quot;共同派生——换台机器或改一行代码，钥匙就打不开了，绑定的是度量值而非身份。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写飞地利用的具体步骤，不复现已公开的 SGX 侧信道攻击。机密计算下一课。</p><p><span class="marginnote">常见误区：容易以为&quot;数据加密、OS 看不见&quot;就万事大吉。OS 仍掌握页换出与计时——观察飞地访问了哪些页、每次耗时多久，照样能推断密钥位；侧信道正是威胁模型里必须明写的那一项。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>票据密钥怕 OS；TEE 对 OS 隔离敏感码。</li><li>SGX 飞地，TrustZone 安全世界。</li><li>侧信道与调用约定仍在模型里。</li><li>下一课机密计算。</li><li>出处：Costan and Devadas；ARM TrustZone；<a href="/cs/isolation-sandbox">isolation-sandbox</a>。</li></ul>',6))])}const f=i(p,[["render",u]]);export{C as __pageData,f as default};
